using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace HarborValeGreybox.Racing.Editor {
public static class LineupAssets {
 const string Root="Assets/HarborValeGreybox/Lineup/";static int meshSerial;static string model;static Material paint,glass,metal,rubber,white,red;
 static Material Mat(string name,Color color,float metallic=0){string p=Root+"Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(m==null){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,p);}m.color=color;m.SetFloat("_Metallic",metallic);m.SetFloat("_Glossiness",metallic>0?.48f:.23f);return m;}
 static GameObject Box(Transform root,string name,Vector3 p,Vector3 size,Material m,bool collision=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(root,false);g.transform.localPosition=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;if(!collision)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static void Prism(Transform root,string name,Vector3[] side,float width,Material mat){var v=new List<Vector3>();foreach(float x in new[]{-width/2,width/2})foreach(var p in side)v.Add(new Vector3(x,p.y,p.z));var t=new List<int>();int n=side.Length;for(int i=1;i<n-1;i++){t.AddRange(new[]{0,i+1,i,n,n+i,n+i+1});}for(int i=0;i<n;i++){int j=(i+1)%n;t.AddRange(new[]{i,j,n+i,j,n+j,n+i});}var mesh=new Mesh{name=name};mesh.SetVertices(v);mesh.SetTriangles(t,0);mesh.RecalculateNormals();mesh.RecalculateBounds();string path=Root+"Meshes/"+model+"_"+(meshSerial++)+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null)AssetDatabase.CreateAsset(mesh,path);else{EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}var g=new GameObject(name);g.transform.SetParent(root,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;}
 static void Wheel(Transform root,string name,float x,float z,VehicleSpec s){var pivot=new GameObject(name);pivot.transform.SetParent(root,false);pivot.transform.localPosition=new Vector3(x,s.wheelRadius+.12f,z);foreach(var item in new[]{("Tire",s.wheelRadius*2,.22f,rubber),("Alloy rim",s.wheelRadius*1.45f,.235f,metal),("Hub",s.wheelRadius*.42f,.245f,paint)}){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=item.Item1;g.transform.SetParent(pivot.transform,false);g.transform.localRotation=Quaternion.Euler(0,0,90);g.transform.localScale=new Vector3(item.Item2,item.Item3/2,item.Item2);g.GetComponent<Renderer>().sharedMaterial=item.Item4;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());}for(int i=0;i<5;i++){float a=i*72*Mathf.Deg2Rad;var spoke=Box(pivot.transform,"Rim spoke",new Vector3(Mathf.Sign(x)*.12f,Mathf.Sin(a)*s.wheelRadius*.37f,Mathf.Cos(a)*s.wheelRadius*.37f),new Vector3(.015f,.035f,s.wheelRadius*.68f),white);spoke.transform.localRotation=Quaternion.Euler(i*-72,0,0);}}
 static void Car(VehicleSpec s){model=s.id;meshSerial=0;var g=new GameObject(s.name+" | original "+s.shape+" visual");paint=Mat(s.id+"_Paint",new Color(s.color[0],s.color[1],s.color[2]),.5f);float front=s.length/2,rear=-front,axle=s.wheelBase/2,top=s.wheelRadius*2+.13f;
  Prism(g.transform,"Body shell / shoulder",new[]{new Vector3(0,top,rear),new Vector3(0,top,front),new Vector3(0,top+.13f,front-.20f),new Vector3(0,top+.25f,axle-.15f),new Vector3(0,top+.23f,-axle+.1f),new Vector3(0,top+.12f,rear+.1f)},s.width,paint);
  float clear=s.wheelRadius+.04f;Box(g.transform,"Body shell / center sill",new Vector3(0,top*.65f,0),new Vector3(s.width,top*.7f,s.wheelBase-2*clear),paint);float overhang=(s.length-s.wheelBase)/2-clear;foreach(float side in new[]{-1f,1f})Box(g.transform,"Body shell / bumper skirt",new Vector3(0,top*.65f,side*(front-overhang/2)),new Vector3(s.width,.32f,Mathf.Max(.15f,overhang)),paint);
  float cabinFront=s.shape=="muscle"?.38f:s.shape=="sedan"?.85f:.65f,cabinBack=s.shape=="sedan"?-1.25f:-.95f,roofFront=s.shape=="muscle"?-.12f:.15f,roofBack=s.shape=="sedan"?-.9f:-.65f;Prism(g.transform,"Dark cabin glazing",new[]{new Vector3(0,top+.15f,cabinBack),new Vector3(0,top+.18f,cabinFront),new Vector3(0,s.height-.06f,roofFront),new Vector3(0,s.height-.06f,roofBack)},s.width*.79f,glass);Box(g.transform,"Roof panel",new Vector3(0,s.height-.035f,(roofFront+roofBack)/2),new Vector3(s.width*.8f,.07f,roofFront-roofBack+.08f),paint);
  foreach(float x in new[]{-1f,1f}){Box(g.transform,"Body shell / B pillar",new Vector3(x*s.width*.405f,(s.height+top)/2,-.35f),new Vector3(.04f,s.height-top,.09f),paint);Box(g.transform,"Mirror",new Vector3(x*(s.width/2+.055f),top+.2f,cabinFront-.25f),new Vector3(.13f,.11f,.22f),metal);Box(g.transform,"Door handle",new Vector3(x*(s.width/2+.012f),top+.06f,-.35f),new Vector3(.03f,.03f,.16f),metal);if(s.shape=="sedan")Box(g.transform,"Rear door handle",new Vector3(x*(s.width/2+.012f),top+.06f,-1.0f),new Vector3(.03f,.03f,.15f),metal);}
  if(s.shape=="muscle"){Box(g.transform,"Hood center bulge",new Vector3(0,top+.3f,1.05f),new Vector3(.64f,.11f,1.25f),paint);foreach(float x in new[]{-.26f,.26f})Box(g.transform,"Hood intake",new Vector3(x,top+.36f,1.4f),new Vector3(.14f,.035f,.32f),rubber);}
  Box(g.transform,"Front grille",new Vector3(0,top-.03f,front+.018f),new Vector3(s.width*.54f,.16f,.035f),rubber);for(int i=-1;i<=1;i+=2){Box(g.transform,"Headlamp",new Vector3(i*s.width*.35f,top+.04f,front+.026f),new Vector3(s.shape=="muscle"?.33f:.42f,s.shape=="coupe"?.085f:.12f,.035f),white);Box(g.transform,"Tail lamp",new Vector3(i*s.width*.35f,top+.05f,rear-.026f),new Vector3(.4f,.1f,.035f),red);Box(g.transform,"Exhaust",new Vector3(i*s.width*.34f,.35f,rear-.04f),new Vector3(.13f,.10f,.14f),metal);}
  Box(g.transform,"Front plate",new Vector3(0,top-.20f,front+.04f),new Vector3(.46f,.12f,.02f),white);Box(g.transform,"Rear plate",new Vector3(0,top-.14f,rear-.04f),new Vector3(.46f,.12f,.02f),white);string[] names={"Front left wheel pivot","Front right wheel pivot","Rear left wheel pivot","Rear right wheel pivot"};for(int i=0;i<4;i++)Wheel(g.transform,names[i],i%2==0?-s.track/2:s.track/2,i<2?axle:-axle,s);PrefabUtility.SaveAsPrefabAsset(g,Root+"Resources/"+s.id+".prefab");UnityEngine.Object.DestroyImmediate(g);
 }
 static void Garage(){var g=new GameObject("Harbor Vale Motor Works | three open bays");var concrete=Mat("Garage_concrete",new Color(.45f,.46f,.44f));var wall=Mat("Garage_wall",new Color(.29f,.34f,.35f));var dark=Mat("Garage_dark",new Color(.06f,.1f,.12f));var accent=Mat("Garage_teal",new Color(.08f,.65f,.57f));var timber=Mat("Garage_worktop",new Color(.37f,.24f,.12f));Box(g.transform,"Left structural wall",new Vector3(-8.85f,2.4f,0),new Vector3(.3f,4.8f,12),wall,true);Box(g.transform,"Right structural wall",new Vector3(8.85f,2.4f,0),new Vector3(.3f,4.8f,12),wall,true);Box(g.transform,"Rear structural wall",new Vector3(0,2.4f,5.85f),new Vector3(18,4.8f,.3f),wall,true);Box(g.transform,"Roof",new Vector3(0,4.85f,0),new Vector3(18.3f,.2f,12.3f),dark,true);Box(g.transform,"Epoxy floor | original foundation supports tires",new Vector3(0,.095f,0),new Vector3(17.8f,.025f,11.8f),concrete);Box(g.transform,"Door header / 3.6m clearance",new Vector3(0,4.2f,-5.9f),new Vector3(18,1.2f,.25f),dark,true);foreach(float x in new[]{-8.7f,-3f,3f,8.7f})Box(g.transform,"Bay structural post",new Vector3(x,1.8f,-5.9f),new Vector3(.25f,3.6f,.3f),wall,true);
  foreach(float x in new[]{-5.8f,0f,5.8f}){Box(g.transform,"Raised open roller shutter",new Vector3(x,3.9f,-5.7f),new Vector3(5.4f,.4f,.35f),metal);foreach(float z in new[]{-3.5f,0f,3.5f})Box(g.transform,"Bay LED strip",new Vector3(x,4.68f,z),new Vector3(.16f,.03f,1.8f),white);foreach(float offset in new[]{-1.4f,1.4f})Box(g.transform,"Floor bay guide",new Vector3(x+offset,.113f,-.7f),new Vector3(.06f,.008f,7),accent);Box(g.transform,"Workbench worktop",new Vector3(x,.96f,4.65f),new Vector3(2.2f,.13f,.7f),timber,true);foreach(float leg in new[]{-.9f,.9f})Box(g.transform,"Workbench leg",new Vector3(x+leg,.48f,4.65f),new Vector3(.09f,.9f,.5f),metal,true);Box(g.transform,"Tool cabinet",new Vector3(x+1.9f,.55f,4.6f),new Vector3(.7f,1.1f,.65f),accent,true);for(int i=0;i<5;i++)Box(g.transform,"Drawer",new Vector3(x+1.9f,.22f+i*.18f,4.26f),new Vector3(.57f,.025f,.02f),metal);}
  Box(g.transform,"Exterior teal fascia",new Vector3(0,4.2f,-6.08f),new Vector3(17.6f,.72f,.08f),accent);Box(g.transform,"Office screen",new Vector3(8.66f,1.4f,2),new Vector3(.06f,.55f,.85f),glass);Box(g.transform,"Office counter",new Vector3(7.8f,.94f,2),new Vector3(1.8f,.1f,1.2f),timber,true);PrefabUtility.SaveAsPrefabAsset(g,Root+"Resources/PhysicalGarage.prefab");UnityEngine.Object.DestroyImmediate(g);
 }
 public static void Build(){foreach(var folder in new[]{"Materials","Meshes","Resources"})System.IO.Directory.CreateDirectory(Root+folder);AssetDatabase.Refresh();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);glass=Mat("Glazing",new Color(.045f,.10f,.14f),.18f);metal=Mat("Metal",new Color(.36f,.41f,.44f),.72f);rubber=Mat("Rubber",new Color(.025f,.03f,.035f));white=Mat("Lamp_white",new Color(.83f,.90f,.91f));red=Mat("Lamp_red",new Color(.65f,.035f,.025f));foreach(var s in VehicleLineup.All)if(s.id!="car_tempest")Car(s);Garage();TempestImport.Prepare();AssetDatabase.SaveAssets();}
}
